package com.goldenunicorn.troopmanager.model

/** v0.65: authored scenes, no runtime-generated dialogue or rotating generic buttons. */
object RelationshipContentCatalog {
    private fun choice(id: String, label: String, reaction: String, priority: CompanionPriority?, category: String, topic: String): RelationshipChoice {
        val effect = when (category) {
            "politics" -> RelationshipEffect(trust = 1, respect = 1, satisfaction = 1, topic = topic, issueSeverity = -8)
            "hospital" -> RelationshipEffect(trust = 2, affection = 1, topic = topic, issueSeverity = -10)
            "war", "frontier" -> RelationshipEffect(respect = 2, loyalty = 1, topic = topic, issueSeverity = -6)
            else -> RelationshipEffect(trust = 2, affection = 1, topic = topic, issueSeverity = -6)
        }
        return RelationshipChoice(id, label, reaction, effect = effect, priority = priority, resolvesIssue = true,
            consequenceHint = if (category == "politics") "Eine gemeinsame politische Linie; nach drei Tagen meldet der Rat die ersten Reaktionen." else "Ein persönlicher Moment; ihr klärt das benannte Thema.",
            delayedEffect = if (category == "politics" && id.endsWith(":1")) RelationshipEffect(satisfaction = 1, tradeDays = if (topic == "Handel") 2 else 0) else null,
            delayDays = if (category == "politics" && id.endsWith(":1")) 3 else 0,
            delayedText = if (category == "politics" && id.endsWith(":1")) "Der Rat greift eure Entscheidung auf: $label $reaction" else "")
    }
    private fun scene(key: String, category: String, title: String, text: String, topic: String, requirements: Set<String>, priority: CompanionPriority,
        a: String, ar: String, b: String, br: String, c: String, cr: String): RelationshipScenario = RelationshipScenario(
        key, title, text, category, topic, requirements = requirements,
        weight = if (category in setOf("war", "hospital", "politics")) 14 else 10,
        preferredPriority = priority,
        variants = variants[key] ?: listOf("Ein vertraulicher Brief ergänzt heute die offene Frage.", "Eine unabhängige Beobachtung gibt dem Gespräch eine zweite Perspektive."),
        options = listOf(choice("$key:0", a, ar, priority, category, topic), choice("$key:1", b, br,
            if (priority == CompanionPriority.DEFENSE) CompanionPriority.DIPLOMACY else CompanionPriority.DEFENSE, category, topic),
            RelationshipChoice("$key:2", c, cr, consequenceHint = "Ihr vertagt oder begrenzt die gemeinsame Zeit ohne persönlichen Nachteil.", boundary = true)))

