        scene("player_injured", "hospital", "Die ungetragene Rüstung", "Deine Rüstung steht neben dem Lazarettbett. {name} fragt, welche Aufgaben wirklich auf deine Genesung warten müssen.", "Verwundete", setOf("player_wounded"), CompanionPriority.WOUNDED, "Die dringenden Aufgaben gemeinsam delegieren.", "Ihr erkennt, welche Arbeit andere tragen können, bis du gesund bist.", "Die Heilerin zuerst nach deiner Belastbarkeit fragen.", "Der Rat folgt einem medizinischen Maßstab statt einem Ehrgefühl.", "Heute keine Regierungsgespräche führen.", "{name} nimmt deinen Wunsch nach Ruhe ernst."),
        scene("beds_short", "hospital", "Die Betten im Gang", "Im Lazarett stehen Betten im Gang. {name} bemerkt, dass die Sanitäter kaum noch einen freien Platz haben.", "Verwundete", setOf("wounded"), CompanionPriority.WOUNDED, "Einen stillen Saal für die Genesenden öffnen.", "Die Verwundeten gewinnen Ruhe; die Garnison hilft beim Umräumen.", "Die Sanitäter nach ihrem dringendsten Bedarf fragen.", "Ihr hört den Menschen zu, die den Alltag der Station kennen.", "Heute nur besuchen und zuhören.", "Der Besuch muss kein Leistungsversprechen werden; sie akzeptiert das."),
        scene("soldier_letter", "hospital", "Der ungeöffnete Brief", "Ein verletzter Soldat bittet {name}, einen Brief an seine Familie zu lesen; er hat Angst vor den Antworten.", "Familie", setOf("wounded"), CompanionPriority.FAMILY, "Mit seiner Zustimmung beim Antworten helfen.", "Der Soldat entscheidet selbst, welche Nachricht seine Familie erhält.", "Seinen Kameraden als vertrauten Beistand holen.", "Er bekommt Unterstützung von jemandem, der seine Geschichte kennt.", "Seine Privatsphäre wahren und weitergehen.", "Niemand wird zu einem Gespräch gedrängt."),
        scene("healer_argument", "hospital", "Ein Streit um Heilkräuter", "Zwei Heiler streiten über die letzten Kräuter. {name} will wissen, wer die Vorräte künftig verteilt.", "Versorgung", setOf("wounded"), CompanionPriority.SUPPLY, "Die Heiler gemeinsame Dringlichkeitsregeln aufstellen lassen.", "Die Station dokumentiert, warum ein Patient Vorrang erhält.", "Eine feste Vorratsverantwortliche benennen.", "Ein klarer Ansprechpartner beendet das tägliche Gerangel.", "Die fachliche Entscheidung den Heilern überlassen.", "Ihr greift nicht in die Behandlung ein und bleibt ansprechbar."),
        scene("recovered_veteran", "hospital", "Die erste Runde ohne Krücke", "Ein Veteran geht erstmals ohne Krücke über den Hof. {name} fragt, was Rückkehr in den Dienst für ihn bedeuten soll.", "Verwundete", setOf("wounded"), CompanionPriority.WOUNDED, "Mit ihm über einen freiwilligen Ausbildungsdienst sprechen.", "Seine Erfahrung zählt, auch wenn die Front keine passende Aufgabe mehr ist.", "Seine Genesung ohne neue Dienstfrage feiern.", "Heute wird seine Rückkehr als Mensch und Kamerad gewürdigt.", "Den Veteranen heute nicht ansprechen.", "Ihr respektiert seinen eigenen Moment."),
        scene("night_shift", "hospital", "Die letzte Nachtwache", "Die Sanitäter schlafen im Sitzen. {name} kann eine Stunde bei den wachen Patienten verbringen oder die Helfer ablösen lassen.", "Verwundete", setOf("wounded"), CompanionPriority.WOUNDED, "Eine Stunde bei den wachen Patienten bleiben.", "Ihr hört kleine Geschichten, die im Einsatzbericht keinen Platz finden.", "Freiwillige für eine ruhige Ablösung sammeln.", "Die Sanitäter können ausruhen, ohne ihre Patienten allein zu lassen.", "Den Besuch für heute beenden.", "Eure gemeinsame Zeit hat eine Grenze; sie nimmt diese ohne Vorwurf an."),
        scene("tax_bread", "politics", "Abgaben auf Brot", "{name} zeigt den Steuerzettel einer Bäckersfamilie: hohe Abgaben und teures Mehl treffen denselben Haushalt.", "Steuern", setOf("high_tax"), CompanionPriority.SUPPLY, "Die Härtefälle gemeinsam prüfen lassen.", "Der Rat sieht konkrete Haushalte hinter der Steuersumme.", "Die Versorgung der Bäckereien zuerst sichern.", "Ein Versorgungsplan soll Preisdruck lindern, ohne die ganze Kasse sofort neu zu ordnen.", "Heute keine gemeinsame Steuerzusage machen.", "Sie hört deine Grenze und verlangt kein Versprechen auf Vorrat."),
        scene("refugee_gate", "politics", "Familien am Tor", "Flüchtlinge warten am Tor. {name} möchte Sicherheit prüfen, aber Familien nicht tagelang im Regen stehen lassen.", "Flüchtlinge", setOf("refugees"), CompanionPriority.INTEGRATION, "Eine geschützte Aufnahme mit überprüfbaren Listen organisieren.", "Die Wache kann prüfen und die Familien finden Schutz.", "Zuerst Gastgeber aus der Stadt gewinnen.", "Bürger bieten Plätze an; die Aufnahme wird zur gemeinsamen Aufgabe.", "Das Gespräch nach dem Torbericht fortsetzen.", "Ihr braucht verlässliche Informationen; sie nimmt die Pause sachlich an."),
        scene("occupation_school", "politics", "Zwei Sprachen im Schulraum", "In einem besetzten Ort streiten die Lehrer über die Sprache der Kinder. {name} warnt vor einer erzwungenen Einheitslösung.", "Integration", setOf("occupation"), CompanionPriority.INTEGRATION, "Unterricht in beiden Sprachen vorschlagen.", "Die Kinder behalten ihre Herkunft und können die neue Verwaltung verstehen.", "Die örtlichen Lehrer eine gemeinsame Ordnung entwerfen lassen.", "Ihr gebt den Lehrern Verantwortung statt einer fertigen Hoflösung.", "Heute keine Unterrichtsordnung beschließen.", "Die Frage bleibt offen, ohne persönlichen Schuldvorwurf."),
        scene("prisoners_terms", "politics", "Bedingungen für Gefangene", "Die Wachliste enthält Gefangene ohne Anhörung. {name} fragt, welche Regeln auch in Kriegszeiten gelten sollen.", "Gefangene", setOf("captives"), CompanionPriority.DIPLOMACY, "Öffentliche Fristen für Anhörungen festlegen.", "Die Wachen wissen, welche Verfahren den Gefangenen zustehen.", "Einen neutralen Gesandten zur Beobachtung einladen.", "Das Verfahren bekommt einen Zeugen, der keinem Kriegsflügel angehört.", "Erst die vorhandenen Akten einsehen.", "Ihr beschließt heute keine neue Regel und behandelt einander weiterhin respektvoll."),
        scene("alliance_clause", "politics", "Eine kleine Bündnisklausel", "Eine Gesandtschaft fordert gemeinsame Feldzüge. {name} liest die Klausel zweimal: Hilfe darf nicht jeder fremden Eroberung gelten.", "Kriegspolitik", setOf("diplomacy"), CompanionPriority.DIPLOMACY, "Das Bündnis auf gemeinsame Verteidigung begrenzen.", "Eure Hilfe bleibt berechenbar und schützt den Grenzfrieden.", "Für jeden Feldzug einen eigenen Ratsbeschluss verlangen.", "Der Hof gewinnt Handlungsspielraum, ohne den Partner abzuweisen.", "Heute noch keine Bündnislinie zusagen.", "Sie akzeptiert, dass eine Zusage mehr Zeit braucht."),
        scene("trade_toll", "politics", "Der neue Brückenzoll", "Ein Kaufmann bietet sichere Lieferungen gegen einen niedrigeren Zoll. {name} will die Einnahmen gegen verlässliches Getreide abwägen.", "Handel", setOf("diplomacy"), CompanionPriority.TRADE, "Eine befristete Liefervereinbarung prüfen.", "Ihr verbindet den Preisnachlass mit nachvollziehbaren Lieferungen.", "Die Händler um einen gemeinsamen Vorschlag bitten.", "Mehrere Händler müssen die Last und den Gewinn teilen.", "Heute keine Zollvereinbarung treffen.", "Eine Vertagung wird ohne persönliche Enttäuschungsstrafe angenommen."),
        scene("expansion_fields", "politics", "Grenzen auf bestellten Feldern", "Auf der Karte liegt eine mögliche Expansion über bewirtschafteten Höfen. {name} fragt, wer den Preis eurer Grenze trägt.", "Expansion", emptySet(), CompanionPriority.DEFENSE, "Die Bauern vor einer Grenzänderung anhören.", "Die Karte bekommt Stimmen von Menschen, die dort leben.", "Die Verteidigung bestehender Wege zuerst stärken.", "Ihr entscheidet euch für einen begrenzten Auftrag mit klarer Verantwortung.", "Heute keine neuen Grenzpläne besprechen.", "Ihr lasst die Karte liegen und findet ohne Zwang einen späteren Zeitpunkt."),
        scene("rival_seat", "court", "Der leere Sitz", "Ein Hofmitglied stellt {name}s Stuhl hinter die übrigen Ratsplätze. Sie fragt, ob ihr den Vorgang öffentlich oder direkt klären wollt.", "Hofanerkennung", emptySet(), CompanionPriority.RECOGNITION, "Mit ihr den Ratsplatz offiziell bestätigen.", "Ihre Rolle wird durch eine klare Ordnung statt durch ein persönliches Geschenk sichtbar.", "Das Hofmitglied mit ihr zusammen zur Rede stellen.", "Sie spricht selbst und du stehst neben ihr, ohne für sie zu sprechen.", "Heute keinen Auftritt am Hof planen.", "Sie akzeptiert die Pause; die Anerkennung ihrer Person hängt nicht an diesem Auftritt."),
        scene("rumor_scroll", "court", "Das Gerücht auf Pergament", "Ein Flugblatt behauptet, {name} führe dich allein durch Nähe. Sie möchte ihre Arbeit sichtbar machen, ohne private Dinge öffentlich erklären zu müssen.", "Hofanerkennung", emptySet(), CompanionPriority.RECOGNITION, "Ihre bisherigen Ratsaufgaben öffentlich benennen.", "Der Hof diskutiert ihre Arbeit und muss eure Privatsphäre nicht bewerten.", "Eine unabhängige Zeugin ihre Leistungen berichten lassen.", "Ihr fordert keine bloße Gefolgschaft, sondern überprüfbare Anerkennung.", "Das Gerücht heute nicht öffentlich beantworten.", "Ihre Privatsphäre bleibt gewahrt, und die Pause kostet kein Vertrauen."),
        scene("envoy_insult", "court", "Die spitze Bemerkung", "Ein Gesandter verspottet {name}s Herkunft. Sie bleibt ruhig und fragt nach einer Antwort, die ihre Stimme nicht übergeht.", "Integration", setOf("diplomacy"), CompanionPriority.INTEGRATION, "Ihr das Wort geben und ihre Stellung bekräftigen.", "Sie setzt die Grenze selbst; du bestätigst sie vor dem Gesandten.", "Den Empfang bis zu einer Entschuldigung unterbrechen.", "Die Unterbrechung macht den Maßstab des Hofes deutlich.", "Den Streit später unter vier Augen beraten.", "Ihr vertagt die Antwort, ohne einander die Kränkung anzulasten."),
        scene("council_split", "court", "Drei Stimmen im Rat", "Der Rat ist zwischen Handel, Verteidigung und Ausbau gespalten. {name} fragt nach dem Maßstab, der alle Vorschläge vergleichbar macht.", "Regierung", emptySet(), CompanionPriority.DEFENSE, "Jeden Vorschlag nach Versorgung und Sicherheit prüfen.", "Die Ratsmitglieder sehen, warum eine Aufgabe heute Vorrang bekommt.", "Ein begrenztes Probeprojekt mit Berichtspflicht vorschlagen.", "Ihr schafft eine überprüfbare Entscheidung statt eines dauerhaften Siegers.", "Heute erst die Ratsberichte lesen.", "Die Diskussion bleibt offen und persönlich respektvoll."),
        scene("recognition_badge", "court", "Ein Amt statt eines Schmuckstücks", "Ein Hofmeister bietet {name} ein Ehrenabzeichen. Sie fragt nach den Rechten, die hinter dem Titel stehen.", "Hofanerkennung", setOf("co_rulers"), CompanionPriority.RECOGNITION, "Entscheidungsrechte und Vertretung schriftlich festhalten.", "Ihr Amt gewinnt überprüfbare Verantwortung im Rat.", "Sie selbst ihr Ressort dem Hof vorstellen lassen.", "Der Hof hört ihre Ziele direkt aus ihrer eigenen Stimme.", "Die Zeremonie verschieben, bis die Regeln klar sind.", "Ein späterer Termin wird als Sorgfalt angenommen."),
        scene("petition_queue", "court", "Die lange Bittstellerreihe", "Ein Adeliger verlangt Vorrang vor den Handwerkern. {name} fragt, welche Ordnung eure gemeinsame Sprechstunde braucht.", "Hofanerkennung", emptySet(), CompanionPriority.INTEGRATION, "Nach Dringlichkeit statt nach Rang anhören.", "Ein dringender Werkstattfall erreicht den Rat noch am selben Tag.", "Feste Zeiten für Gruppen mit geringer Hofnähe reservieren.", "Auch Menschen ohne Fürsprecher kennen ihren Zugang zum Hof.", "Heute keine gemeinsame Sprechstunde abhalten.", "Ihr gebt keine Zusage, die ihr heute nicht tragen könnt."),
        scene("joint_signature", "court", "Zwei Unterschriften", "Ein Schreiber legt einen wichtigen Erlass mit nur einer Unterschriftenzeile vor. {name} fragt, wer dafür Verantwortung übernehmen soll.", "Mitregentschaft", setOf("co_rulers"), CompanionPriority.RECOGNITION, "Eure beiden Verantwortungsbereiche im Erlass nennen.", "Zwei Unterschriften bedeuten zwei erkennbare Verantwortlichkeiten.", "Für ihr Ressort ihre eigene Unterschrift vorsehen.", "Ihr bestätigt ihren selbstständigen Auftrag, ohne jede Aufgabe doppelt zu führen.", "Den Erlass vorerst nicht gemeinsam zeichnen.", "Sie akzeptiert, dass ihr heute noch keine gemeinsame Verpflichtung eingeht."),
        scene("children_question", "family", "Eine offene Zukunftsfrage", "{name} fragt, wie Familienleben neben Herrschaft Platz finden könnte. Sie erwartet eine ehrliche Antwort, keinen sofortigen Kinderplan.", "Familie", emptySet(), CompanionPriority.FAMILY, "Über Zeit, Sicherheit und Unterstützung sprechen.", "Ihr sprecht über Voraussetzungen, ohne damit einen Kinderwunsch oder Consent festzulegen.", "Erzählen, welches Familienbild dich geprägt hat.", "Eure verschiedenen Erfahrungen dürfen nebeneinander stehen.", "Heute nicht über Kinder sprechen.", "Ihre Antwort bleibt freundlich; deine Grenze erzeugt keinen Nachteil."),
        scene("expected_room", "family", "Ein Raum für neues Leben", "Für den angekündigten Familienzuwachs muss ein Raum vorbereitet werden. {name} fragt, wie viel Nähe und wie viel Ruhe ihr braucht.", "Familie", setOf("expecting"), CompanionPriority.FAMILY, "Den ruhigen Raum nahe der Familie vorbereiten.", "Ihr plant einen Alltag, der Ruhe und Hilfe verbindet.", "Eine vertraute Betreuungsperson in die Planung holen.", "Die Familie hört eine Erfahrung, die am Ratstisch fehlt.", "Die Planung heute den betreuenden Helfern lassen.", "Ihr müsst nicht jeden Familienmoment zu einer Regierungsentscheidung machen."),
        scene("child_question", "family", "Die Frage nach der Schlacht", "Ein Kind fragt {name}, ob Mut bedeutet, nie Angst zu haben. Sie schaut zu dir, bevor sie antwortet.", "Erziehung", setOf("family"), CompanionPriority.FAMILY, "Von einem Moment erzählen, in dem du Hilfe brauchtest.", "Das Kind hört, dass Mut und Hilfe zusammenpassen.", "Sie von ihrem ersten Kommando erzählen lassen.", "Sie beschreibt Angst als Signal, mit anderen Verantwortung zu teilen.", "Das Kind heute ohne Rat spielen lassen.", "Nicht jede Frage braucht sofort eine gemeinsame Lehrstunde."),
        scene("heir_pressure", "family", "Ein Name auf der Erbenliste", "Ein Höfling redet über ein Kind nur als künftigen Erben. {name} fragt, wie ihr Kindheit und Nachfolge zusammen denkt.", "Erbfolge", setOf("family"), CompanionPriority.FAMILY, "Kindheit und spätere Amtsprüfung deutlich trennen.", "Die Familie schützt freie Entwicklung, ohne die Nachfolgefrage zu leugnen.", "Mehrere mögliche Erben offen ausbilden lassen.", "Der Hof muss Verantwortung als Eignung statt als einzigen Namen sehen.", "Heute keine Nachfolgeerwartung an das Kind richten.", "Ihr setzt eine klare Pause, ohne persönliche Folgen für eure Nähe."),
        scene("mourning_candle", "family", "Eine Kerze am Fenster", "Für einen verlorenen Angehörigen steht eine Kerze am Fenster. {name} fragt nicht nach einer Lösung, sondern nach einer Form des Erinnerns.", "Trauer", emptySet(), CompanionPriority.FAMILY, "Eine kleine Geschichte über den Menschen teilen.", "Die Erinnerung enthält ein gelebtes Leben statt nur den Verlust.", "Still neben ihr bei der Kerze sitzen.", "Euer Schweigen lässt der Trauer ihren eigenen Raum.", "Heute allein trauern wollen.", "Sie respektiert, dass Trauer auch Abstand brauchen darf."),
        scene("distant_letter", "family", "Der Brief aus der Heimat", "Ein Brief von {name}s Herkunftsort nennt eine schlechte Ernte und bittet eher um Rat als um Almosen.", "Herkunft", emptySet(), CompanionPriority.SUPPLY, "Mit ihr einen dauerhaften Versorgungsvorschlag entwerfen.", "Ihre Heimat bleibt Partnerin des Gesprächs und keine bloße Bittstellerin.", "Eine verlässliche Reisende nach der Lage fragen.", "Ihr prüft den Bedarf, bevor ihr etwas versprecht.", "Die Familienpost ihr privat lassen.", "Du achtest ihre Privatsphäre und ihre eigenständigen Kontakte."),
        scene("shared_table", "family", "Ein Platz am Familientisch", "Am Familientisch ist ein Stuhl frei. {name} fragt, ob heute Ratsthemen oder die Geschichten der Kinder Platz bekommen sollen.", "Familie", setOf("family"), CompanionPriority.FAMILY, "Den Rat für diesen Abend bewusst draußen lassen.", "Die Familie bekommt Zeit, die nicht von Berichten gefüllt wird.", "Die Kinder erzählen lassen, was sie an der Burg ändern würden.", "Ein spielerischer Abend zeigt euch ihre Sicht auf den gemeinsamen Alltag.", "Heute nicht an der Familienrunde teilnehmen.", "Eine ehrliche Grenze wird ohne Schuldgefühl angenommen."),
        scene("orc_tracks", "frontier", "Spuren vor der Mauer", "Die Grenzpatrouille meldet Orkspuren. {name} findet, dass die Dörfer mehr als eine Warnung vom Hof brauchen.", "Verteidigung", setOf("frontier"), CompanionPriority.DEFENSE, "Die Dorfwachen in den Patrouillenplan aufnehmen.", "Die Bewohner kennen ihre eigenen Wege und ergänzen die Garnison.", "Zuerst einen stillen Aufklärungstrupp schicken.", "Ihr sucht verlässliche Stärke und Richtung statt eines vorschnellen Angriffs.", "Heute keine gemeinsame Patrouillenzusage geben.", "Sie nimmt die Grenze an; die reguläre Wache bleibt zuständig."),
        scene("uruk_shields", "frontier", "Die schweren Schilde", "Ein Bericht zeigt Uruk-Schilde mit neuen Beschlägen. {name} fragt, ob eure Mauerwache ihre alten Übungen ändern muss.", "Verteidigung", setOf("frontier"), CompanionPriority.DEFENSE, "Die Schildbilder mit den Ausbildern analysieren.", "Die Mauerwache übt gezielt gegen die beobachtete Formation.", "Die Patrouille nach Schwächen abseits der Schilde suchen lassen.", "Ihr ergänzt Stärke durch Wissen über Wege und Versorgung.", "Heute bei den bestehenden Übungen bleiben.", "Ihr verändert heute keinen Ausbildungsplan und wahrt den gegenseitigen Respekt."),
        scene("taotei_sound", "frontier", "Ein Geräusch unter den Steinen", "Nach einer Tao-Tei-Warnung lauscht {name} an einem stillen Mauerabschnitt. Niemand möchte einen Fehlalarm, niemand die Gefahr überhören.", "Verteidigung", setOf("frontier"), CompanionPriority.DEFENSE, "Eine begrenzte Nachtbeobachtung mit Ablösung planen.", "Die Wachen prüfen die Warnung, ohne erschöpft den Morgen zu erreichen.", "Die Goldelben um ihre Beobachtungstechnik bitten.", "Ihr verbindet euer Ortswissen mit der Erfahrung der Verbündeten.", "Heute keinen gemeinsamen Wachdienst übernehmen.", "Sie respektiert eure Grenze; die normale Besatzung hält weiter Wache."),
        scene("gold_elf_help", "frontier", "Die Hilfe der Goldelben", "Goldelbische Verbündete bieten eine kostbare Unterstützung an. {name} möchte ihre Bedingungen verstehen, bevor ihr euch abhängig macht.", "Bündnis", setOf("frontier"), CompanionPriority.DIPLOMACY, "Die Ziele der Verbündeten offen besprechen.", "Eine gemeinsame Zusage beginnt mit geklärten Erwartungen.", "Die Hilfe an einen begrenzten Mauerabschnitt binden.", "Ihr erprobt Zusammenarbeit, bevor daraus eine unbegrenzte Verpflichtung wird.", "Heute noch keine Hilfe zusagen.", "Die Verbündeten erhalten eine ehrliche offene Antwort."),
        scene("wall_weapon", "frontier", "Die neue Mauerwaffe", "Beim Probeaufbau der Mauerwaffe fehlt den Schützen Platz zum Rückzug. {name} zeigt auf den schmalen Durchgang.", "Verteidigung", setOf("frontier"), CompanionPriority.WOUNDED, "Mit den Schützen den sicheren Rückweg üben.", "Die Bedienung gilt erst dann als gelungen, wenn die Mannschaft zurückkommt.", "Den Aufbau mit den Handwerkern versetzen lassen.", "Ein anderer Standort gibt der Mannschaft Raum und verändert die Sichtlinie.", "Den gemeinsamen Test heute abbrechen.", "Der Abbruch wird als erlaubte Grenze respektiert."),
        scene("patrol_children", "frontier", "Die Kinder am Grenzweg", "Bei der Patrouille spielen Kinder an einem alten Warnpfahl. {name} fragt, wie die Grenze schützen kann, ohne das Dorf klein zu halten.", "Integration", setOf("frontier"), CompanionPriority.INTEGRATION, "Mit dem Dorf einen sicheren Spielweg markieren.", "Die Kinder gewinnen Raum und die Patrouille klare Rücksichtspunkte.", "Die Warnzeichen mit Bewohnern erneuern.", "Die Hinweise werden verständlich und verlieren ihren bloß bedrohlichen Ton.", "Die Dorfberatung heute auslassen.", "Ein fehlender gemeinsamer Termin wird euch persönlich nicht angelastet."),
        scene("duo_signal", "frontier", "Ein Signal im Lärm", "Im gemeinsamen Training hört {name} deinen Ruf im Lärm kaum. Sie schlägt ein sichtbares Signal für euer Duo vor.", "Führung", setOf("frontier"), CompanionPriority.DEFENSE, "Drei einfache Handzeichen zusammen erproben.", "Euer Duo findet Zeichen, die auch erschöpfte Wachen lesen können.", "Die ganze Patrouille an den Signalen mitarbeiten lassen.", "Aus eurer Übung entsteht Wissen, das andere ebenfalls schützt.", "Heute auf zusätzliche Übungen verzichten.", "Bond und Freundschaft verlangen keine erzwungene Trainingsstunde."),
        scene("uncertain_command", "personal", "Vor dem ersten Befehl", "{name} hält den Entwurf eines Befehls zurück. Sie weiß, was zu tun ist, zweifelt aber an der Wirkung auf junge Soldaten.", "Führung", emptySet(), CompanionPriority.RECOGNITION, "Den Befehl mit ihr laut durchgehen.", "Sie hört ihre eigene klare Entscheidung und erkennt die offenen Stellen.", "Eine junge Unteroffizierin nach Verständlichkeit fragen.", "Ihr erhaltet eine ehrliche Rückmeldung aus der betroffenen Einheit.", "Den Entwurf ihr zur eigenen Prüfung lassen.", "Du respektierst ihre Selbstständigkeit statt ihr eine Antwort abzunehmen."),
        scene("earned_pride", "personal", "Der selbst verdiente Rang", "{name} zeigt dir eine alte Rangmarke. Sie fragt, welcher Erfolg in eurem Leben wirklich euch selbst gehört.", "Anerkennung", emptySet(), CompanionPriority.RECOGNITION, "Von ihrem eigenständigen Erfolg sprechen.", "Sie merkt, dass du ihre Leistung jenseits eurer Beziehung kennst.", "Einen eigenen Fehler und die spätere Lernarbeit teilen.", "Ihr vergleicht Wege statt Ranglisten und lasst Stolz ohne Überhöhung zu.", "Heute keine persönlichen Erfolge vergleichen.", "Die Pause wird freundlich angenommen."),
        scene("overload_lists", "personal", "Zu viele Listen", "Auf {name}s Tisch liegen Einsatz-, Rats- und Familienlisten. Sie fragt, welche Aufgaben sie abgeben darf, ohne ihr Amt zu verlieren.", "Überforderung", emptySet(), CompanionPriority.WOUNDED, "Mit ihr Aufgaben und Vertretung klar trennen.", "Sie behält Verantwortung und erhält einen tatsächlich tragbaren Alltag.", "Den Rat nach einer festen Unterstützung fragen.", "Ihr sucht einen sichtbaren Helfer statt stiller Mehrarbeit.", "Heute nicht an ihren Listen mitarbeiten.", "Sie nimmt deine Grenze an und kann eigenständig Hilfe suchen."),
        scene("future_window", "personal", "Ein Blick über die Grenze", "{name} fragt, wie ein Frieden aussehen soll, in dem ihr nicht jeden Morgen neue Feinde zählen müsst.", "Gemeinsame Zukunft", emptySet(), CompanionPriority.DIPLOMACY, "Gemeinsame Wege für Handel und Begegnung skizzieren.", "Der Frieden bekommt Orte und Menschen statt nur eine leere Karte.", "Ein begrenztes Verteidigungsziel für die nächste Saison nennen.", "Ein klarer Auftrag macht ein späteres Ende des Feldzugs vorstellbar.", "Heute über etwas Alltägliches sprechen.", "Sie akzeptiert, dass große Zukunftsfragen Zeit brauchen."),
        scene("old_comrade", "personal", "Die bekannte Stimme", "Auf dem Burghof erkennt {name} die Stimme eines früheren Kameraden. Sie ist froh und zugleich unsicher, welche Verpflichtung mit ihm zurückkehrt.", "Vergangenheit", emptySet(), CompanionPriority.RECOGNITION, "Sie den Kameraden in ihrem Tempo begrüßen lassen.", "Du gibst Raum für eine Geschichte, die vor eurem gemeinsamen Weg begann.", "Eine kleine Runde für alte Erinnerungen anbieten.", "Die Begegnung bekommt einen ruhigen Ort, ohne zum Hofauftritt zu werden.", "Heute nicht an der Begegnung teilnehmen.", "Ihre alten Freundschaften brauchen keine ständige Begleitung von dir."),
